<div class="sf-container sf-page-y"><div class="mx-auto max-w-md"><header class="text-center"><p class="sf-eyebrow">Account recovery</p><h1 class="mt-2 text-3xl font-semibold tracking-tight">Choose a new password</h1></header><div class="sf-card mt-8"><form wire:submit="resetPassword" class="space-y-5"><div><label for="reset-email" class="sf-label">Email address</label><input id="reset-email" name="email" type="email" wire:model="email" autocomplete="email" required class="sf-input mt-1 w-full @error('email') sf-input-error @enderror">@error('email')<p class="sf-field-error">{{ $message }}</p>@enderror</div><div><label for="reset-password" class="sf-label">New password</label><input id="reset-password" name="password" type="password" wire:model="password" autocomplete="new-password" required class="sf-input mt-1 w-full @error('password') sf-input-error @enderror">@error('password')<p class="sf-field-error">{{ $message }}</p>@enderror</div><div><label for="reset-password-confirmation" class="sf-label">Confirm new password</label><input id="reset-password-confirmation" name="password_confirmation" type="password" wire:model="passwordConfirmation" autocomplete="new-password" required class="sf-input mt-1 w-full"></div><button class="sf-button sf-button-primary w-full" wire:loading.attr="disabled" wire:target="resetPassword">Reset password</button></form></div></div></div>
